def _h(t):
    return f'<h4 class="e-h4">{t}</h4>'


def _calc_example():
    base = 100000.0
    parts = [("10.11–30.11.2026", 21, 1.0090), ("01.12–31.12.2026", 31, 1.0080), ("01.01–31.01.2027", 31, 1.0085), ("01.02–09.02.2027", 9, 1.0075)]
    rows, tot0, tot1 = [], 0.0, 0.0
    for per, d, k in parts:
        v = round(base * d / 92, 2)
        w = round(v * k, 2)
        tot0 += v
        tot1 += w
        rows.append([per, str(d), ru(v, 2), ru(k, 4), ru(w, 2)])
    rows.append(["<b>Итого</b>", "<b>92</b>", f"<b>{ru(tot0, 2)}</b>", "", f"<b>{ru(tot1, 2)}</b>"])
    return rows


